export function getAttractionReservationEditionRule(rule: AttractionReservationRule, language: AttractionReservationEditionLocale): RuleCopy {
  const translated = ruleCopy[language][rule.id];
  if (!translated || (rule.release && !translated.release) || (rule.price?.kind === 'cny' && !translated.basis) || (rule.disclosure && !translated.disclosure)) {
    throw new Error(`Missing ${language} reservation copy: ${rule.id}`);
  }
  return translated;
}
